{
  "items": [
    {
      "name": "MvPolynomial.eval₂Hom",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] → [inst_1 : CommSemiring S₁] → (R →+* S₁) → (σ → S₁) → MvPolynomial σ R →+* S₁"
    },
    {
      "name": "MvPolynomial.eval_map",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] (f : R →+* S₁)\n  (g : σ → S₁) (p : MvPolynomial σ R), (MvPolynomial.eval g) ((MvPolynomial.map f) p) = MvPolynomial.eval₂ f g p"
    },
    {
      "name": "MvPolynomial.map_eval₂",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {S₂ : Type w} {S₃ : Type x} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]\n  (f : R →+* S₁) (g : S₂ → MvPolynomial S₃ R) (p : MvPolynomial S₂ R),\n  (MvPolynomial.map f) (MvPolynomial.eval₂ MvPolynomial.C g p) =\n    MvPolynomial.eval₂ MvPolynomial.C (⇑(MvPolynomial.map f) ∘ g) ((MvPolynomial.map f) p)"
    },
    {
      "name": "MvPolynomial.map_aeval",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁]\n  {B : Type u_2} [inst_3 : CommSemiring B] (g : σ → S₁) (φ : S₁ →+* B) (p : MvPolynomial σ R),\n  φ ((MvPolynomial.aeval g) p) = (MvPolynomial.eval₂Hom (φ.comp (algebraMap R S₁)) fun i => φ (g i)) p"
    },
    {
      "name": "Polynomial.eval₂RingHom'",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S : Type v} →\n    [inst : Semiring R] →\n      [inst_1 : Semiring S] → (f : R →+* S) → (x : S) → (∀ (a : R), Commute (f a) x) → Polynomial R →+* S"
    }
  ]
}
